import test from 'node:test';import assert from 'node:assert/strict';
import {LocalD1} from '../tools/sqlite.mjs';import {migrate} from '../tools/migrate.mjs';import {seed,createUser} from '../tools/seed.mjs';import {handle} from '../src/worker.mjs';import {orderView,q} from '../src/commerce.mjs';import {sha,token} from '../src/security.mjs';
// Most tests check other rules, so the first-order free delivery (owner 28.10) is off unless a test asks for it.
const env=async({firstFree=false,simple=false}={})=>{const DB=new LocalD1();migrate(DB);await seed(DB,{karo:false});if(!firstFree)DB.exec('UPDATE cities SET first_order_free=0');if(!simple)DB.exec('UPDATE cities SET simple_flow=0');DB.exec('DELETE FROM day_hours');const owner={id:await createUser(DB,{email:'owner@test.invalid',name:'Тестовый владелец',password:'test-password-123456',owner:true}),owner:true,memberships:[]};return{DB,owner}};
async function call(e,path,b,user=null){const headers=b?{'Content-Type':'application/json','X-Bazar-CSRF':'1'}:{};if(user){const session=token();await q(e.DB,'INSERT INTO sessions(hash,user_id,expires) VALUES(?,?,?)',await sha(session),user.id,Date.now()+100000).run();headers.cookie='bazar_session='+session}const r=await handle(new Request('https://bazar.test/api/'+path,{method:b?'POST':'GET',headers,...(b?{body:JSON.stringify(b)}:{})}),e);return{...await r.json(),http:r.status}}
const cid='akhalkalaki',pid=k=>cid+'--'+k,vendor=cid+'-garden';
async function order(e,items=[{product_id:pid('apple_loose'),selection:{grams:1000}},{product_id:pid('pear_loose'),selection:{grams:1000}}]){const base={city_id:cid,items,fulfillment:'delivery'},quote=await call(e,'quote',base);assert.equal(quote.http,200);const b={...base,idem:crypto.randomUUID(),day:new Date(Date.now()+86400000).toISOString().slice(0,10),minute:600,method:'cash',customer:{name:'Тестовый покупатель',phone:'+995555000000',address:'Тестовый адрес, не доставлять'},expected_total:quote.total,maximum_total:quote.maximum_total,accepted_weight_rules:true,privacy_consent:true};const o=await call(e,'orders',b);assert.equal(o.http,201,JSON.stringify(o));return{o,b}}
async function view(e,o,user=e.owner){return orderView(e.DB,o.id,user)}
async function act(e,o,action,extra={},user=e.owner){const current=await view(e,o,user);const b={id:o.id,version:current.version,command:crypto.randomUUID(),action,...extra};const r=await call(e,'manage/action',b,user);assert.equal(r.http,200,JSON.stringify({action,r}));return b}
async function collected(e,o,collector=e.owner,controller=e.owner){assert.equal((await view(e,o)).status,'ASSEMBLING');await act(e,o,'submit_collection',{},collector);assert.equal((await view(e,o)).status,'CHECKING');await act(e,o,'check_collection',{},controller);const c=await view(e,o);assert.equal(c.status,'CUSTOMER_REVIEW');const r=await call(e,'order/confirm',{id:o.id,key:o.key,version:c.version,accepted:true});assert.equal(r.http,200,JSON.stringify(r));assert.equal((await view(e,o)).status,'READY')}
async function member(e,role,suffix='one',v=vendor){const id=await createUser(e.DB,{email:role+suffix+'@test.invalid',name:role,password:'test-password-123456',vendor_id:v,role});return{id,owner:false,memberships:[{vendor_id:v,role}]}}
test('98 localized products, private costs, city boundaries and price tampering',async()=>{const e=await env();try{const c=await call(e,'catalog?city='+cid);assert.equal(c.products.length,49);assert.ok(c.products.every(p=>p.names.hy&&p.names.ka&&p.names.ru&&!('cost'in p)));const x=await call(e,'quote',{city_id:'tbilisi',items:[{product_id:pid('apple_loose'),selection:{grams:1000}}],fulfillment:'pickup'});assert.equal(x.http,409);const{o,b}=await order(e);const replay=await call(e,'orders',b);assert.equal(replay.id,o.id);assert.equal(replay.key,o.key);assert.equal((await q(e.DB,'SELECT COUNT(*) n FROM orders').first()).n,1);assert.equal((await call(e,'orders',{...b,expected_total:1,idem:crypto.randomUUID()})).http,409)}finally{e.DB.close()}});
test('two suppliers: claim lock, isolated details, weighing, ready, delivery and separate payment',async()=>{const e=await env();try{const{o}=await order(e),d=await member(e,'DRIVER'),d2=await member(e,'DRIVER','two'),s1=await member(e,'SUPPLIER'),s2=await member(e,'SUPPLIER','two',cid+'-farm');const unassigned=await view(e,o,d);assert.equal(unassigned.customer,undefined);await act(e,o,'claim',{},d);const c=await view(e,o);assert.equal((await call(e,'manage/action',{id:o.id,version:c.version,command:crypto.randomUUID(),action:'claim'},d2)).http,403);await act(e,o,'confirm',{},d);const scoped=await view(e,o,s1);assert.equal(scoped.customer,null);assert.equal(scoped.total,null);assert.equal(scoped.quotes.length,1);await act(e,o,'available',{vendor_id:vendor},s1);await act(e,o,'available',{vendor_id:cid+'-farm'},s2);await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1090}]},s1);assert.equal((await view(e,o)).actuals,null);await act(e,o,'weigh',{actuals:[{line_id:pid('pear_loose'),net_g:950}]},s2);assert.equal((await view(e,o)).status,'ASSEMBLING');assert.equal((await view(e,o)).proposal,null);for(const [u,v]of[[s1,vendor],[s2,cid+'-farm']]){await act(e,o,'prepare',{vendor_id:v},u);await act(e,o,'ready',{vendor_id:v},u)}await collected(e,o);for(const a of['pickup','depart','deliver'])await act(e,o,a,{},d);let current=await view(e,o);assert.equal(current.status,'COMPLETED');assert.equal(current.payment,'UNPAID');await act(e,o,'payment',{amount:200,reason:'Тестовая частичная оплата'});assert.equal((await view(e,o)).payment,'PARTIAL');current=await view(e,o);const pay=await act(e,o,'payment',{amount:current.total-current.paid,reason:'Тестовое подтверждение'});assert.equal((await call(e,'manage/action',pay,e.owner)).http,200);assert.equal((await view(e,o)).payment,'PAID');assert.equal((await q(e.DB,'SELECT COUNT(*) n FROM payments').first()).n,2);assert.equal((await q(e.DB,'SELECT reserved FROM slots WHERE city_id=?',cid).first()).reserved,0);assert.ok((await q(e.DB,'SELECT COUNT(*) n FROM outbox WHERE status=?','DISABLED').first()).n>10);assert.equal((await q(e.DB,'SELECT stock FROM products WHERE id=?',pid('apple_loose')).first()).stock,98910)}finally{e.DB.close()}});
test('outside tolerance requires buyer capability and explicit approval; original snapshot remains',async()=>{const e=await env();try{const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);await act(e,o,'confirm');await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1300}]});let current=await view(e,o);assert.equal(current.status,'AWAITING_APPROVAL');assert.equal(current.actuals,null);const b={id:o.id,key:o.key,version:current.version,proposal_id:current.proposal.id,approved:true};assert.equal((await call(e,'order/approve',{...b,key:'wrong'})).http,404);const result=await call(e,'order/approve',b);assert.equal(result.status,'ASSEMBLING');assert.equal(result.total,1085);assert.equal(result.original_quotes[0].target_g,1000);assert.equal((await call(e,'order/approve',b)).http,409)}finally{e.DB.close()}});
test('replacement is buyer-approved and keeps initial product plus history',async()=>{const e=await env();try{const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);await act(e,o,'confirm');await act(e,o,'missing',{vendor_id:vendor});await act(e,o,'replace',{items:[{product_id:pid('pear_loose'),selection:{grams:1000}}]});const c=await view(e,o);assert.equal(c.quotes[0].product_id,pid('apple_loose'));const r=await call(e,'order/approve',{id:o.id,key:o.key,version:c.version,proposal_id:c.proposal.id,approved:true});assert.equal(r.quotes[0].product_id,pid('pear_loose'));assert.equal(r.original_quotes[0].product_id,pid('apple_loose'));assert.ok(r.events.find(x=>x.event==='CHANGE_APPROVED').data.proposal);assert.equal((await q(e.DB,'SELECT reserved FROM products WHERE id=?',pid('apple_loose')).first()).reserved,0)}finally{e.DB.close()}});
test('stock reservation is atomic; cancellation releases stock; invalid dates are controlled',async()=>{const e=await env();try{await q(e.DB,'UPDATE products SET stock=1100 WHERE id=?',pid('apple_loose')).run();const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);const bad=await call(e,'quote',{city_id:cid,fulfillment:'pickup',items:[{product_id:pid('apple_loose'),selection:{grams:100}}]});assert.equal(bad.http,409);await act(e,o,'cancel',{reason:'Тест'});assert.equal((await q(e.DB,'SELECT reserved FROM products WHERE id=?',pid('apple_loose')).first()).reserved,0);assert.equal((await call(e,'order/view',{id:o.id})).http,401);assert.equal((await call(e,'manage/orders?city='+cid)).http,401)}finally{e.DB.close()}});
test('one-time invitations, CSRF, no identity-header trust on generic Worker',async()=>{const e=await env();try{const inv=await call(e,'manage/invite',{vendor_id:vendor,role:'SUPPLIER'},e.owner);assert.equal(inv.http,200);const join={invite:inv.invite,name:'Тест',email:'invited@test.invalid',password:'a-long-test-password'};assert.equal((await call(e,'join',join)).http,200);assert.equal((await call(e,'join',{...join,email:'other@test.invalid'})).http,409);const r=await handle(new Request('https://bazar.test/api/manage/team',{headers:{'oai-authenticated-user-id':'fake-owner'}}),e);assert.equal(r.status,401);const bad=await handle(new Request('https://bazar.test/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),e);assert.equal(bad.status,403)}finally{e.DB.close()}});
test('net income closure requires known expense lines and at least ten percent',async()=>{const e=await env();try{const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);await act(e,o,'confirm');await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1000}]});await q(e.DB,"UPDATE orders SET status='COMPLETED' WHERE id=?",o.id).run();const current=await view(e,o);await act(e,o,'payment',{amount:current.total,reason:'Тест'});const expenses=Object.fromEntries(['seller_payout','delivery','payment','packaging','gift','tax','marketing','overhead','reserve','other'].map(k=>[k,0]));const base={id:o.id,command:crypto.randomUUID(),version:0,costs_confirmed:true,expenses:{...expenses,seller_payout:900},evidence:'Учебный расчёт, подтверждены все статьи'};const r=await call(e,'manage/settle',base,e.owner);assert.equal(r.state,'SHORTFALL');assert.equal(r.required_net,95);assert.equal(r.net,50);const closed=await call(e,'manage/settle',{...base,command:crypto.randomUUID(),version:1,expenses:{...expenses,seller_payout:855}},e.owner);assert.equal(closed.state,'CLOSED');assert.equal(closed.net,95);assert.equal((await call(e,'manage/settle',{...base,command:crypto.randomUUID(),version:2},e.owner)).http,409);const summary=await call(e,'manage/summary?city='+cid,null,e.owner);assert.equal(summary.gross_profit,null);assert.equal(summary.received,950)}finally{e.DB.close()}});
test('out-of-range reweigh cannot mark suppliers ready before buyer approval',async()=>{const e=await env();try{const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);await act(e,o,'confirm');await act(e,o,'available',{vendor_id:vendor});await act(e,o,'prepare',{vendor_id:vendor});await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1000}]});await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1300}]});const c=await view(e,o);assert.equal((await call(e,'manage/action',{id:o.id,version:c.version,command:crypto.randomUUID(),action:'ready',vendor_id:vendor},e.owner)).http,403)}finally{e.DB.close()}});
test('owner creates category and products; supplier cannot; stock and translations survive reseeding',async()=>{const e=await env();try{const b={id:'new-market',names:{ru:'С рынка',hy:'Շուկայից',ka:'ბაზრიდან'},command:crypto.randomUUID()};assert.equal((await call(e,'manage/category/create',b,e.owner)).http,200);const p={code:'new-almond',names:{ru:'Тестовый миндаль',hy:'Փորձնական նուշ',ka:'სატესტო ნუში'},vendor_id:vendor,category:'new-market',art:'almond',mode:'WEIGHED',price:3000,cost:null,stock:3000,minimum_g:100,order_step_g:50,tolerance_cap_g:20,reason:'Учебный товар',command:crypto.randomUUID()};const r=await call(e,'manage/product/create',p,e.owner);assert.equal(r.http,200);assert.equal((await call(e,'manage/product/create',p,e.owner)).id,r.id);const supplier=await member(e,'SUPPLIER');assert.equal((await call(e,'manage/product/create',{...p,command:crypto.randomUUID(),code:'other'},supplier)).http,403);await q(e.DB,'UPDATE products SET stock=2500 WHERE id=?',r.id).run();await seed(e.DB,{karo:false});assert.equal((await q(e.DB,'SELECT stock FROM products WHERE id=?',r.id).first()).stock,2500);const c=await call(e,'catalog?city='+cid);assert.ok(c.categories.find(c=>c.id==='new-market'));assert.equal(c.products.find(p=>p.id===r.id).price,3000)}finally{e.DB.close()}});
test('new cities and suppliers can be added without source edits',async()=>{const e=await env();try{const cityBody={code:'batumi',names:{ru:'Батуми',hy:'Բաթում',ka:'ბათუმი'},delivery_fee:700,command:crypto.randomUUID()};assert.equal((await call(e,'manage/city/create',cityBody,e.owner)).http,200);const supplier=await call(e,'manage/vendor/create',{code:'orchard',city_id:'batumi',names:{ru:'Учебный сад Батуми',hy:'Բաթումի փորձնական այգի',ka:'ბათუმის სატესტო ბაღი'},address:'Тестовый пункт выдачи',phone:'',command:crypto.randomUUID()},e.owner);assert.equal(supplier.http,200);const c=await call(e,'catalog?city=batumi');assert.equal(c.vendors.length,1);assert.equal(c.city.delivery_fee,700);assert.equal(c.products.length,0);assert.equal((await call(e,'bootstrap')).cities.length,3)}finally{e.DB.close()}});
test('owner can perform courier actions only after claiming the order',async()=>{const e=await env();try{const{o}=await order(e,[{product_id:pid('apple_loose'),selection:{grams:1000}}]);await act(e,o,'claim');await act(e,o,'confirm');await act(e,o,'available',{vendor_id:vendor});await act(e,o,'weigh',{actuals:[{line_id:pid('apple_loose'),net_g:1000}]});const sp=await member(e,'SUPPLIER','p'+crypto.randomUUID().slice(0,6));await act(e,o,'prepare',{vendor_id:vendor},sp);await act(e,o,'ready',{vendor_id:vendor},sp);await collected(e,o);for(const a of['pickup','depart','deliver'])await act(e,o,a);assert.equal((await view(e,o)).status,'COMPLETED')}finally{e.DB.close()}});
test('restarting local development never reapplies migrations or destroys stock',async()=>{const e=await env();try{await q(e.DB,'UPDATE products SET stock=7777 WHERE id=?',pid('apple_loose')).run();const migrationCount=(await q(e.DB,'SELECT COUNT(*) n FROM _local_migrations').first()).n;migrate(e.DB);await seed(e.DB,{karo:false});assert.equal((await q(e.DB,'SELECT stock FROM products WHERE id=?',pid('apple_loose')).first()).stock,7777);assert.equal((await q(e.DB,'SELECT COUNT(*) n FROM _local_migrations').first()).n,migrationCount)}finally{e.DB.close()}});
test('market departments: cheese, trout and others are ready for suppliers, each with a licensed photo and three-language labels',async()=>{const e=await env();try{const {newArts}=await import('../src/categories.mjs'),{artLabels}=await import('../public/photos.js'),fs=await import('node:fs');const c=await call(e,'catalog?city='+cid);for(const id of['dairy','eggs','bread','meat','trout','deli','preserves','pantry','drinks','household'])assert.ok(c.categories.find(x=>x.id===id&&x.names.ru&&x.names.hy&&x.names.ka),id);assert.ok(!c.categories.find(x=>x.id==='fish'));assert.deepEqual(Object.keys(artLabels).sort(),[...newArts].sort());for(const a of newArts){assert.ok(fs.existsSync(new URL('../public/media/'+a+'.jpg',import.meta.url)),a);assert.ok(artLabels[a].ru&&artLabels[a].hy&&artLabels[a].ka,a)}const p={code:'trout-paravani',names:{ru:'Форель',hy:'Իշխան',ka:'კალმახი'},vendor_id:vendor,category:'trout',art:'trout',mode:'WEIGHED',price:2500,cost:null,stock:5000,minimum_g:500,order_step_g:100,tolerance_cap_g:200,reason:'Учебный товар',command:crypto.randomUUID()};const r=await call(e,'manage/product/create',p,e.owner);assert.equal(r.http,200,JSON.stringify(r));assert.equal((await call(e,'catalog?city='+cid)).products.find(x=>x.id===r.id).art,'trout')}finally{e.DB.close()}});
test('Karo supplier: owner prices = cost + group markup (15/20/30%) rounded up to 10 tetri, costs recorded, migration equals seed, reapplying changes nothing',async()=>{const DB=new LocalD1();migrate(DB);await seed(DB);try{const fs=await import('node:fs'),{karoSql,karoMoves,karoProducts,retail,karoArtsWithoutPhoto}=await import('../src/karo.mjs'),{profileFor}=await import('../src/weight-profiles.mjs');assert.deepEqual([400,330,850,150,4800].map(retail),[520,430,1110,200,6240]);const sql=fs.readFileSync(new URL('../migrations/0008_karo_supplier.sql',import.meta.url),'utf8');assert.ok(sql.endsWith(karoSql(profileFor).join('\n')+'\n'),'migration must be regenerated from src/karo.mjs');const e={DB},c=await call(e,'catalog?city='+cid);const {amoProducts,amoOffal,amoRetired,amoPieces,amoRemoved}=await import('../src/amo.mjs');assert.equal(c.products.length,49+karoProducts.length-1+amoProducts.length+amoOffal.length-amoRetired.length+amoPieces.length-1-amoRemoved.length+1+1+5-3-1-1+1+40+31+40-1,'duplicate dark beans retired; Amo added, offal split; Kristall drinks; jam closed');const karo=c.products.filter(p=>p.vendor_id==='akhalkalaki-karo');const {karoVarieties,karoVarietyPrice,karoVarietySql,karoVarietiesRetired2}=await import('../src/karo-varieties.mjs');assert.equal(karo.length,karoMoves.length+karoProducts.length+karoVarieties.length-karoVarietiesRetired2.length);assert.equal(c.products.find(p=>p.id===pid('red_beans')).price,910);assert.ok(!c.products.find(p=>p.id===pid('beans_speckled_dark')));const {karoFixSql}=await import('../src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0010_karo_red_beans.sql',import.meta.url),'utf8').endsWith(karoFixSql().join('\n')+'\n'),'migration 0010 must be regenerated from src/karo.mjs');const {karoJarSql}=await import('../src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0011_karo_jar_volume.sql',import.meta.url),'utf8').endsWith(karoJarSql().join('\n')+'\n'));assert.equal(c.products.find(p=>p.id===pid('tomato_pickled_jar')).names.ru,'Помидоры маринованные · банка 3 л');const {karoPhotoSql}=await import('../src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0012_karo_red_apple_photo.sql',import.meta.url),'utf8').endsWith(karoPhotoSql().join('\n')+'\n'));assert.equal(c.products.find(p=>p.id===pid('apple_loose')).art,'apple-star','the red-apple photo, later replaced by the owner\'s «Стар» photo (24.10)');assert.equal((await q(DB,"SELECT art FROM products WHERE id='tbilisi--apple_loose'").first()).art,'apple');assert.ok(c.vendors.find(v=>v.id==='akhalkalaki-karo'&&v.names.hy&&v.names.ka));const {karoTierSql,karoKeepSql,karoPrice,karoCosts}=await import('../src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0017_karo_keep_competitive.sql',import.meta.url),'utf8').endsWith(karoKeepSql().join('\n')+'\n'),'migration 0017 must be regenerated from src/karo.mjs');const {karoUndoSql}=await import('../src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0018_karo_conference_pear.sql',import.meta.url),'utf8').endsWith(karoUndoSql().join('\n')+'\n'),'migration 0018 must be regenerated from src/karo.mjs');assert.ok(fs.readFileSync(new URL('../migrations/0016_karo_tiered_markup.sql',import.meta.url),'utf8').endsWith(karoTierSql().join('\n')+'\n'),'migration 0016 must be regenerated from src/karo.mjs');assert.equal(karoCosts().length+karoVarieties.length-karoVarietiesRetired2.length,karo.length,'every Karo product has a markup group');for(const [key,cost]of karoCosts()){const row=await q(DB,'SELECT price,cost,vendor_id FROM products WHERE id=?',pid(key)).first();assert.deepEqual([row.price,row.cost,row.vendor_id],[karoPrice(key,cost),cost,'akhalkalaki-karo'],key)}assert.deepEqual(['potato_loose','apple_loose','tomato_loose','pear_loose','champignon_loose','walnut_kernel'].map(k=>c.products.find(p=>p.id===pid(k)).price),[130,460,690,960,1320,2860]);assert.equal(c.products.find(p=>p.id===pid('pineapple_each')).profile.mode,'EACH');assert.equal((await q(DB,"SELECT vendor_id FROM products WHERE id='tbilisi--apple_loose'").first()).vendor_id,'tbilisi-garden');const {remotePhotos}=await import('../public/photos.js');for(const p of karo)if(!karoArtsWithoutPhoto.includes(p.art)&&!remotePhotos[p.art])assert.ok(fs.existsSync(new URL('../public/media/'+p.art+'.jpg',import.meta.url)),p.art);const before=JSON.stringify((await DB.prepare('SELECT * FROM products ORDER BY id').all()).results);DB.exec(sql);await seed(DB);assert.equal(JSON.stringify((await DB.prepare('SELECT * FROM products ORDER BY id').all()).results),before)}finally{DB.close()}});
test('supplier daily settlement: only delivered orders count at cost; supplier agrees; payments reduce debt and cannot exceed it; reversal restores it',async()=>{const e=await env();try{await q(e.DB,'UPDATE products SET cost=400 WHERE id=?',pid('apple_loose')).run();const deliver=async items=>{const{o}=await order(e,items),d=await member(e,'DRIVER','x'+crypto.randomUUID().slice(0,6));await act(e,o,'claim',{},d);await act(e,o,'confirm',{},d);await act(e,o,'available',{vendor_id:vendor});await act(e,o,'weigh',{actuals:items.map(i=>({line_id:i.product_id,net_g:1100}))});await act(e,o,'prepare',{vendor_id:vendor});await act(e,o,'ready',{vendor_id:vendor});await collected(e,o);for(const a of['pickup','depart','deliver'])await act(e,o,a,{},d);return o};
 const apple=[{product_id:pid('apple_loose'),selection:{grams:1000}}];await deliver(apple);await deliver(apple);const cancelled=(await order(e,apple)).o;await act(e,cancelled,'cancel',{reason:'Покупатель отказался'});
 const supplier=await member(e,'SUPPLIER'),stranger=await member(e,'SUPPLIER','far',cid+'-farm');let l=await call(e,'manage/ledger?city='+cid,null,e.owner);let g=l.vendors.find(v=>v.id===vendor);assert.equal(g.open_days.length,1);const day=g.open_days[0];assert.equal(day.lines.length,2,'cancelled order is not owed');assert.equal(day.amount,880,'1.1 kg × 4.00 twice');
 assert.equal((await call(e,'manage/ledger/fix',{vendor_id:vendor,day:day.day,command:crypto.randomUUID()},supplier)).http,403);const fix={vendor_id:vendor,day:day.day,command:crypto.randomUUID()},f=await call(e,'manage/ledger/fix',fix,e.owner);assert.equal(f.amount,880);assert.equal((await call(e,'manage/ledger/fix',fix,e.owner)).id,f.id);assert.equal((await call(e,'manage/ledger/fix',{...fix,command:crypto.randomUUID()},e.owner)).http,409);
 assert.equal((await call(e,'manage/ledger/answer',{statement_id:f.id,agree:true},stranger)).http,403);assert.equal((await call(e,'manage/ledger/answer',{statement_id:f.id,agree:false},supplier)).http,400,'disagreement needs a reason');assert.equal((await call(e,'manage/ledger/answer',{statement_id:f.id,agree:false,note:'Было 1.2 кг'},supplier)).http,200);g=(await call(e,'manage/ledger?city='+cid,null,e.owner)).vendors.find(v=>v.id===vendor);assert.equal(g.open_days[0].amount,880,'disputed lines return to the open day');assert.equal(g.balance.debt,0);
 const again=await call(e,'manage/ledger/fix',{vendor_id:vendor,day:day.day,command:crypto.randomUUID()},e.owner);assert.equal(again.http,200);const view=await call(e,'manage/ledger?city='+cid,null,supplier);assert.deepEqual(view.vendors.map(v=>v.id),[vendor],'supplier sees only its own ledger');assert.equal((await call(e,'manage/ledger/answer',{statement_id:again.id,agree:true},supplier)).http,200);
 g=(await call(e,'manage/ledger?city='+cid,null,e.owner)).vendors.find(v=>v.id===vendor);assert.deepEqual([g.balance.agreed,g.balance.debt,g.open_days.length],[880,880,0]);
 assert.equal((await call(e,'manage/ledger/pay',{vendor_id:vendor,amount:881,method:'cash',reason:'Опечатка',command:crypto.randomUUID()},e.owner)).http,409);const pay=await call(e,'manage/ledger/pay',{vendor_id:vendor,amount:400,method:'cash',reason:'Наличные вечером',command:crypto.randomUUID()},e.owner);assert.equal(pay.http,200);assert.equal((await call(e,'manage/ledger/pay',{vendor_id:vendor,amount:100,method:'cash',reason:'x',command:crypto.randomUUID()},supplier)).http,403);
 g=(await call(e,'manage/ledger?city='+cid,null,e.owner)).vendors.find(v=>v.id===vendor);assert.deepEqual([g.balance.paid,g.balance.debt],[400,480]);assert.equal((await call(e,'manage/ledger/reverse',{payment_id:pay.id,reason:'Записали не тому поставщику',command:crypto.randomUUID()},e.owner)).http,200);assert.equal((await call(e,'manage/ledger/reverse',{payment_id:pay.id,reason:'Повтор',command:crypto.randomUUID()},e.owner)).http,409);g=(await call(e,'manage/ledger?city='+cid,null,e.owner)).vendors.find(v=>v.id===vendor);assert.deepEqual([g.balance.paid,g.balance.debt],[0,880])}finally{e.DB.close()}});
